using System;using System.Collections;using System.Collections.Generic;using System.Reflection;using System.IO;using UnityEngine;
public sealed class DoorKeyRulesValidation:MonoBehaviour {
 const BindingFlags F=BindingFlags.NonPublic|BindingFlags.Instance;DungeonPrototype d;DungeonSaveData original;string oldPath;bool oldEnabled;readonly List<string> results=new List<string>();public bool Done{get;private set;}
 object Get(string n){return typeof(DungeonPrototype).GetField(n,F).GetValue(d);}object Call(string n,params object[] args){return typeof(DungeonPrototype).GetMethod(n,F).Invoke(d,args);}void Check(bool ok,string n){results.Add((ok?"PASS ":"FAIL ")+n);}
 Dictionary<string,DungeonDoor> Doors{get{return (Dictionary<string,DungeonDoor>)Get("mapDoors");}}
 IEnumerator WaitDoor(DungeonDoor door){float end=Time.realtimeSinceStartup+8;while(door.IsOpening&&Time.realtimeSinceStartup<end)yield return null;}
 void Restore(DungeonSaveData data){d.RestoreDungeonSave(DungeonMapPersistence.Copy(data));typeof(DungeonPrototype).GetField("startMenuOpen",F).SetValue(d,false);Time.timeScale=1;AudioListener.pause=false;}
 void Cross(DungeonDoor door,bool reverse=false){var a=door.transform.TransformPoint(new Vector3(0,1.5f,-door.doorwayWidth*.5f));var b=door.transform.TransformPoint(new Vector3(0,1.5f,door.doorwayWidth*.5f));door.CheckPassage(reverse?b:a,reverse?a:b);}
 public void Run(){StartCoroutine(Checks());}
 IEnumerator Checks(){d=UnityEngine.Object.FindFirstObjectByType<DungeonPrototype>();original=d.CaptureDungeonSave();oldEnabled=d.enabled;oldPath=DungeonSaveStore.editorTestPath;Directory.CreateDirectory("Tests");DungeonSaveStore.editorTestPath=Path.GetFullPath("Tests/DoorKeyRulesSave.json");
 try{d.enabled=false;var data=DungeonMapPersistence.Copy(original);data.introductionCompleted=true;data.city.inCity=false;var definitions=DungeonMapSettings.Current.entities.objects;var locked=definitions.Find(e=>e.kind==DungeonEntityKind.Door&&e.doorKind==DungeonDoorKind.Locked);var normal=definitions.Find(e=>e.kind==DungeonEntityKind.Door&&e.doorKind==DungeonDoorKind.Normal);if(locked==null||normal==null)throw new Exception("Missing door fixtures");data.interactions.unlockedConnections.Clear();foreach(var state in data.entityStates){state.opened=false;state.keyConsumed=false;}data.player.inventory.RemoveAll(i=>definitions.Exists(e=>e.kind==DungeonEntityKind.Door&&e.requiredKeyId==i.itemId));Restore(data);
 var keyDoor=Doors[locked.id];Call("InteractMapEntity",locked);Check(!keyDoor.IsOpen&&!keyDoor.IsOpening,"Locked door rejects missing key");Check(d.AcquireItem(locked.requiredKeyId,1),"Key fixture added through inventory");Call("InteractMapEntity",locked);Call("InteractMapEntity",locked);yield return WaitDoor(keyDoor);Check(keyDoor.IsOpen&&keyDoor.IsPermanentlyOpen,"Key door permanently opens after animation");Check(!(bool)Call("HasMapKey",locked.requiredKeyId),"Used key removed from inventory");Check(d.CaptureDungeonSave().entityStates.Find(s=>s.id==locked.id).keyConsumed,"Unlock stored on existing entity state");Cross(keyDoor);Cross(keyDoor,true);keyDoor.CloseDoor();keyDoor.SetClosedImmediately();Check(keyDoor.IsOpen&&!keyDoor.IsOpening&&!keyDoor.blocker.enabled,"Permanent key door resists crossings and close commands");
 var unlocked=d.CaptureDungeonSave();DungeonSaveStore.Write(unlocked,0,"Door rules fixture");Restore(data);Check(!keyDoor.IsOpen&&!keyDoor.IsPermanentlyOpen,"Loading an older unopened state resets runtime permanent flag");Restore(DungeonSaveStore.Read(0));keyDoor=Doors[locked.id];Check(keyDoor.IsOpen&&keyDoor.IsPermanentlyOpen&&!(bool)Call("HasMapKey",locked.requiredKeyId),"Save/load restores permanent opening without key");Call("RefreshMapEntityStates",false);Check(keyDoor.IsOpen,"Ordinary refresh cannot relock consumed-key door");
 var json=JsonUtility.ToJson(unlocked);var old=JsonUtility.FromJson<DungeonSaveData>(json.Replace(",\"keyConsumed\":true","").Replace(",\"keyConsumed\":false",""));old.player.inventory.Add(new InventoryItemRecord{itemId=locked.requiredKeyId,quantity=1});Restore(old);Check(keyDoor.IsPermanentlyOpen&&!(bool)Call("HasMapKey",locked.requiredKeyId),"Old opened-key save migrates and consumes retained key once");Call("RefreshMapEntityStates",true);Check(keyDoor.IsOpen,"Repeated restore refresh keeps migrated opening");
 Restore(data);keyDoor=Doors[locked.id];d.AcquireItem(locked.requiredKeyId,1);Call("InteractMapEntity",locked);keyDoor.SetClosedImmediately();Check((bool)Call("HasMapKey",locked.requiredKeyId)&&!d.CaptureDungeonSave().entityStates.Find(s=>s.id==locked.id).keyConsumed,"Cancelled opening does not consume the key");
 var door=Doors[normal.id];door.SetOpenImmediately();Cross(door);yield return WaitDoor(door);Check(!door.IsOpen&&door.blocker.enabled,"Normal door closes after forward passage");Check(!d.CaptureDungeonSave().entityStates.Find(s=>s.id==normal.id).opened,"Auto-close updates persistent door state");door.SetOpenImmediately();Cross(door,true);yield return WaitDoor(door);Check(!door.IsOpen,"Normal door also closes after reverse passage");
 bool noPlate=true;foreach(Transform child in d.GetComponentsInChildren<Transform>())noPlate&=child.name!="Zone warning backplate";Check(noPlate,"Warning text has no black backplate");var npc=definitions.Find(e=>e.kind==DungeonEntityKind.NPC&&e.cell==new Vector2Int(17,34));Check(npc.displayName=="Cerrojio"&&Array.TrueForAll(npc.dialogue,l=>l.speaker=="Cerrojio"),"Independent guide NPC is Cerrojio");Check(Array.Find(RefugeSettings.Current.npcs,n=>n.id=="centinela").displayName=="Solid Guarda","Refuge sentinel keeps Solid Guarda");
 }finally{d.RestoreDungeonSave(original);d.enabled=oldEnabled;DungeonSaveStore.editorTestPath=oldPath;Done=true;File.WriteAllLines("Tests/DoorKeyRulesResults.txt",results);Debug.Log("Door key rules\n"+string.Join("\n",results.ToArray()));}
 }
}
